    correction: [{"quoi":"نرفع القوس المربّع الأول","math":"<span dir=\"ltr\" class=\"expr\">- [x - (z + y)] = -x + z + y</span>"},{"quoi":"نرفع القوس المربّع الثاني","math":"<span dir=\"ltr\" class=\"expr\">- [(-x + y - 1) + (-5 - y)] = x - y + 1 + 5 + y</span>"},{"quoi":"نكتب العبارة بدون أقواس","math":"<span dir=\"ltr\" class=\"expr\">B = -1 - x + z + y + x - y + 1 + 5 + y</span>"},{"quoi":"نجمّع الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">B = (-x + x) + (y - y + y) + z + (-1 + 1 + 5)</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">-1 + 1 + 5 = 5</span>"},{"quoi":"الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">B = y + z + 5</span>"}],
